-- Covers EVERY event from Senior + Junior Summary of Results:
--   MAJOR, BOARD/MIND, LARONG PINOY  → tournaments + points
--   LITERARY/MUSICAL                 → bonus points only
-- Division-gauntlet style ranks match the official sheets.
-- ============================================================

START TRANSACTION;

SET @fest_id = (SELECT id FROM sport_fest_events WHERE year=2026 AND name='High School SGO Days 2026' LIMIT 1);
SET @admin_id = (SELECT id FROM users WHERE role='admin' LIMIT 1);

