INSERT INTO department_scores (department_id, sport_fest_id, total_points, bonus_points, gold_medals, silver_medals, bronze_medals, total_participations, tournaments_entered)
SELECT d.id, @fest_id, 0, 0, 0, 0, 0, 0, 0
FROM departments d
WHERE d.code IN ('BBEES','DOLPHIN','DPEACOCK','MANTIS','NOWL','PANTHER','REDFOX','SGOAT','STALLION','PYTHON','EAGLE')
  AND d.is_active = 1
ON DUPLICATE KEY UPDATE department_id = department_id;

