  tournament_name VARCHAR(150) NOT NULL,
  sport_code VARCHAR(40) NOT NULL,
  gender VARCHAR(20) DEFAULT 'open',
  dept_code VARCHAR(20) NOT NULL,
  rank_pos INT NOT NULL,
  medal VARCHAR(20) NULL,
  points INT NOT NULL,
  category VARCHAR(30) NOT NULL
);

