-- ============================================================
-- 2. CREATE MISSING TOURNAMENTS
-- ============================================================
INSERT INTO tournaments (name, sport_id, sport_fest_id, format, gender, status, start_date, end_date, created_by)
SELECT DISTINCT r.tournament_name,
       COALESCE(
         (SELECT id FROM sports WHERE code = r.sport_code LIMIT 1),
         (SELECT id FROM sports WHERE code = REPLACE(r.sport_code,'_','') LIMIT 1),
         (SELECT id FROM sports LIMIT 1)
       ),
       @fest_id, 'free_for_all', r.gender, 'completed', '2026-09-14', '2026-09-16', @admin_id
FROM tmp_all_results r
WHERE NOT EXISTS (SELECT 1 FROM tournaments t WHERE t.name = r.tournament_name);

INSERT IGNORE INTO sport_fest_tournaments (sport_fest_id, tournament_id)
SELECT @fest_id, t.id FROM tournaments t
WHERE t.name IN (SELECT DISTINCT tournament_name FROM tmp_all_results);

INSERT IGNORE INTO tournament_participants (tournament_id, department_id, status, no_points)
SELECT t.id, d.id, 'active', CASE WHEN d.is_exhibition = 1 THEN 1 ELSE 0 END
FROM tournaments t
JOIN tmp_all_results r ON r.tournament_name = t.name
JOIN departments d ON d.code = r.dept_code
GROUP BY t.id, d.id;

-- ============================================================
-- 3. COMPLETE ALL SEEDED MATCHES
-- ============================================================
UPDATE matches m
JOIN tournaments t ON m.tournament_id = t.id
SET m.status = 'completed',
    m.completed_at = COALESCE(m.completed_at, '2026-09-15 16:00:00')
WHERE t.sport_fest_id = @fest_id
  AND m.status IN ('scheduled','pending','ongoing');

-- Chess Men division-gauntlet winners
UPDATE matches m JOIN tournaments t ON m.tournament_id=t.id AND t.name='Chess (Men) - SGO Days 2026'
SET m.winner_department_id=(SELECT id FROM departments WHERE code='BBEES'), m.completed_at='2026-09-14 08:25:00'
WHERE m.bracket_position='JHS-A';
