SET m.winner_department_id=(SELECT id FROM departments WHERE code='PANTHER'), m.completed_at='2026-09-14 10:25:00'
WHERE m.bracket_position='SHS-A';
UPDATE matches m JOIN tournaments t ON m.tournament_id=t.id AND t.name='Chess (Men) - SGO Days 2026'
SET m.winner_department_id=(SELECT id FROM departments WHERE code='STALLION'), m.completed_at='2026-09-14 11:25:00'
WHERE m.bracket_position='SHS-B';
