UPDATE matches m JOIN tournaments t ON m.tournament_id=t.id AND t.name='Chess (Men) - SGO Days 2026'
SET m.participant_a_department_id=(SELECT id FROM departments WHERE code='PANTHER'),
    m.participant_b_department_id=(SELECT id FROM departments WHERE code='STALLION'),
    m.winner_department_id=(SELECT id FROM departments WHERE code='STALLION'), m.completed_at='2026-09-15 09:25:00'
