UPDATE matches m JOIN tournaments t ON m.tournament_id=t.id AND t.name='Chess (Men) - SGO Days 2026'
SET m.participant_a_department_id=(SELECT id FROM departments WHERE code='REDFOX'),
    m.participant_b_department_id=(SELECT id FROM departments WHERE code='BBEES'),
    m.winner_department_id=(SELECT id FROM departments WHERE code='REDFOX'), m.completed_at='2026-09-15 14:55:00'
WHERE m.bracket_position='CH-JHS';
UPDATE matches m JOIN tournaments t ON m.tournament_id=t.id AND t.name='Chess (Men) - SGO Days 2026'
SET m.participant_a_department_id=(SELECT id FROM departments WHERE code='STALLION'),
    m.participant_b_department_id=(SELECT id FROM departments WHERE code='PANTHER'),
    m.winner_department_id=(SELECT id FROM departments WHERE code='STALLION'), m.completed_at='2026-09-15 15:55:00'
WHERE m.bracket_position='CH-SHS';

INSERT INTO match_results (match_id, total_score_a, total_score_b, final_score_display, winner_side, win_type, recorded_by)
SELECT m.id,
  CASE WHEN m.winner_department_id=m.participant_a_department_id THEN 1 ELSE 0 END,
  CASE WHEN m.winner_department_id=m.participant_b_department_id THEN 1 ELSE 0 END,
  CASE WHEN m.winner_department_id=m.participant_a_department_id THEN '1-0'
       WHEN m.winner_department_id=m.participant_b_department_id THEN '0-1' ELSE '0-0' END,
  CASE WHEN m.winner_department_id=m.participant_a_department_id THEN 'a'
       WHEN m.winner_department_id=m.participant_b_department_id THEN 'b' ELSE NULL END,
  'normal', @admin_id
FROM matches m JOIN tournaments t ON m.tournament_id=t.id
WHERE t.sport_fest_id=@fest_id AND m.status='completed'
  AND NOT EXISTS (SELECT 1 FROM match_results mr WHERE mr.match_id=m.id);

-- ============================================================
-- 4. tournament_results FROM SHEETS
-- ============================================================
DELETE tr FROM tournament_results tr
JOIN tournaments t ON tr.tournament_id=t.id
WHERE t.sport_fest_id=@fest_id AND t.name IN (SELECT DISTINCT tournament_name FROM tmp_all_results);

INSERT INTO tournament_results (tournament_id, department_id, `rank`, medal, sport_fest_points, finalized_at)
SELECT t.id, d.id, r.rank_pos, r.medal, r.points, '2026-09-16 18:00:00'
FROM tmp_all_results r
JOIN tournaments t ON t.name=r.tournament_name
JOIN departments d ON d.code=r.dept_code;

UPDATE tournaments t SET t.status='completed', t.updated_at=NOW()
WHERE t.sport_fest_id=@fest_id AND t.name IN (SELECT DISTINCT tournament_name FROM tmp_all_results);

UPDATE tournaments SET status='completed', updated_at=NOW()
WHERE sport_fest_id=@fest_id AND status!='completed';

