-- ============================================================
-- 6. REBUILD department_scores
-- ============================================================
UPDATE department_scores
SET total_points=0, gold_medals=0, silver_medals=0, bronze_medals=0,
    total_participations=0, tournaments_entered=0, bonus_points=0
WHERE sport_fest_id=@fest_id;

UPDATE department_scores ds
JOIN (
  SELECT tr.department_id,
    SUM(tr.sport_fest_points) AS pts,
    SUM(CASE WHEN tr.medal='gold' THEN 1 ELSE 0 END) AS g,
    SUM(CASE WHEN tr.medal='silver' THEN 1 ELSE 0 END) AS s,
    SUM(CASE WHEN tr.medal='bronze' THEN 1 ELSE 0 END) AS b,
    COUNT(*) AS cnt
  FROM tournament_results tr
  JOIN tournaments t ON tr.tournament_id=t.id
  JOIN sport_fest_tournaments sft ON sft.tournament_id=t.id AND sft.sport_fest_id=@fest_id
  GROUP BY tr.department_id
) x ON ds.department_id=x.department_id AND ds.sport_fest_id=@fest_id
SET ds.total_points=x.pts, ds.gold_medals=x.g, ds.silver_medals=x.s,
    ds.bronze_medals=x.b, ds.total_participations=x.cnt, ds.tournaments_entered=x.cnt;

UPDATE department_scores ds
JOIN (
  SELECT department_id, SUM(points) AS bonus
  FROM sport_fest_bonus_points WHERE sport_fest_id=@fest_id GROUP BY department_id
) b ON ds.department_id=b.department_id AND ds.sport_fest_id=@fest_id
SET ds.bonus_points=b.bonus, ds.total_points=ds.total_points+b.bonus;

DROP TEMPORARY TABLE IF EXISTS tmp_all_results;

COMMIT;

