-- Fill any remaining completed matches that still lack match_results
INSERT INTO match_results (match_id, total_score_a, total_score_b, final_score_display, winner_side, win_type, recorded_by)
SELECT m.id,
  CASE WHEN m.winner_department_id = m.participant_a_department_id THEN 2 ELSE 0 END,
  CASE WHEN m.winner_department_id = m.participant_b_department_id THEN 2 ELSE 0 END,
  CASE WHEN m.winner_department_id = m.participant_a_department_id THEN '2-0'
       WHEN m.winner_department_id = m.participant_b_department_id THEN '0-2' ELSE '0-0' END,
  CASE WHEN m.winner_department_id = m.participant_a_department_id THEN 'a'
       WHEN m.winner_department_id = m.participant_b_department_id THEN 'b' ELSE NULL END,
  'normal', @admin_id
FROM matches m
JOIN tournaments t ON m.tournament_id = t.id
WHERE t.sport_fest_id = @fest_id
  AND m.status = 'completed'
  AND m.winner_department_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM match_results mr WHERE mr.match_id = m.id);

